-- ============================================================
-- Move the fifteen official operators onto the zones they are actually
-- contracted for. Phase 6 recorded them against the programme row because
-- there was nowhere else to put them; each row already carries its zone code
-- in source_title, which is what the join below matches on.
-- ============================================================
update regulated_zone_providers p
set zone_id = z.id,
    last_verified_at = now()
from regulated_towing_zones z
where z.province = 'ON'
  and z.zone_code is not null
  and p.source_title like '%(zone ' || z.zone_code || ')'
  and p.zone_id <> z.id;

-- ============================================================
-- Retire the programme-level row. It is not deleted: it carries the audit
-- history of how Ontario was represented before the zones had boundaries, and
-- deleting it would take that history with it. effective_to closes it, so
-- regulated_zone_in_force() stops returning it regardless of `active`.
-- ============================================================
update regulated_towing_zones
set active = false,
    effective_to = current_date - 1,
    geometry_note = geometry_note || ' SUPERSEDED 2026-09-01 by the fifteen individual zone rows, '
      || 'each with a derived geometry. Kept for its audit history.'
where province = 'ON'
  and zone_code is null
  and official_name = 'Restricted Towing Zones — Tow Zone Program (GTHA)';

-- ============================================================
-- Quebec: still no boundary, and now three official sources checked rather
-- than one. Recorded on the row so the gap is visible where the decision is
-- made, not only in a report.
-- ============================================================
update regulated_towing_zones
set geometry_note = geometry_note || ' RECHECKED 2026-09-01 for Phase 6.1: quebec.ca still describes '
      || 'the territory in prose and links an image map; Donnees Quebec publishes the MTMD road '
      || 'network (Reseau routier - RTSS, with autoroute functional classification) but no layer for '
      || 'the exclusive-towing territory; and the current official fee schedule (Towing service fees '
      || 'for permitted activities, 1 August to 31 October 2026) contains rates and definitions only, '
      || 'with no territorial annex. The blocker is not the road network, which is available - it is '
      || 'that "sections of the North and South shores" has no published extent, so any polygon would '
      || 'be a guess about where the regime stops. Zone stays inactive.',
    last_verified_at = now()
where province = 'QC'
  and official_name = 'Remorquage exclusif — région métropolitaine de Montréal';
